// Demo: Model Context Manager - public implementations survey
(function(){'use strict';
var DATA={"label": "Model Context Manager - public implementations survey", "prog": [["PUSH", 9], ["PUSH", 4], ["ADD"], ["PUSH", 3], ["MUL"], ["PRINT"]]};

